import copy
import hashlib
import json
from pathlib import Path
root=Path.cwd()
local=root/'build/call-contracts-paired-20261002'
orchestration=json.loads((local/'orchestration.json').read_text())
assert orchestration['complete'] and orchestration['passed']
def digest(path):return hashlib.sha256(path.read_bytes()).hexdigest()
public={'schema':'talven.call-contracts-evidence.v1','complete':True,'passed':True,'source_base_revision':'7f23aa1','started_at':orchestration['started_at'],'finished_at':orchestration['finished_at'],'orders':orchestration['orders'],'inputs':orchestration['inputs'],'conditions':{'named':'default persistent direct-callee signatures include parameter names','types':'explicit --call-type-contracts; current displayed signatures reconstructed'},'reports':[],'workload_texts':[],'reuse_sets':{},'orchestration_sha256':digest(local/'orchestration.json'),'orchestration_script':(root/'build/compare-call-contracts.py').read_text(),'curation_script':Path(__file__).read_text()}
for row in orchestration['reports']:
 directory=local/f"pair-{row['pair']}-{row['condition']}"
 raw=json.loads((directory/'report.json').read_text())
 assert raw['complete'] and raw['passed'] and len(raw['samples'])==336 and all(s['verified'] for s in raw['samples'])
 r=copy.deepcopy(raw);r.pop('git_status',None)
 r['commands']=[{k:v for k,v in c.items() if k not in ('argv','stdout','stderr')} | {stream:{k:v for k,v in c[stream].items() if k!='path'} for stream in ('stdout','stderr')} for c in raw['commands']]
 for sample in r['samples']:
  if sample.get('reuse') is not None:
   reuse=sample.pop('reuse');key=hashlib.sha256(json.dumps(reuse,sort_keys=True).encode()).hexdigest()
   public['reuse_sets'][key]=reuse;sample['reuse_set']=key
 if not public['workload_texts']:
  for workload in raw['workloads']:
   for rev in workload['revisions']:
    d=directory/'workloads'/workload['id']/rev['id']
    public['workload_texts'].append({'workload':workload['id'],'revision':rev['id'],'source':(d/'source.tal').read_text(),'oracle':(d/'oracle.c').read_text() if (d/'oracle.c').exists() else None})
 public['reports'].append({'pair':row['pair'],'condition':row['condition'],'raw_report_sha256':digest(directory/'report.json'),'receipt':r})
metadata={k:v for k,v in public.items() if k not in ('curation_script','orchestration_script')}
assert all(prefix not in json.dumps(metadata) for prefix in ('/Users/','/private/','/var/folders/'))
p=root/'experiments/results/call-contracts-macos-arm64-20261002.json';p.write_text(json.dumps(public,sort_keys=True,indent=2)+'\n')
print(p.name,p.stat().st_size,digest(p));print('wall',public['started_at'],public['finished_at'])
print('compiler',sorted({r['receipt']['compiler_hash'] for r in public['reports']}))

orchestration_script:
import hashlib
import json
import os
from pathlib import Path
import subprocess
import sys
from datetime import datetime, timezone
root=Path.cwd()
result=root/'build/call-contracts-paired-20261002'
result.mkdir()
files=sorted([*root.joinpath('talven').glob('*.py'),root/'scripts/measure-incremental.py',root/'scripts/measure-tooling.py',root/'experiments/__init__.py',root/'experiments/tooling_workloads.py',*root.joinpath('examples').glob('*.tal')])
def identity(path): return hashlib.sha256(path.read_bytes()).hexdigest()
report={'schema':'talven.call-contracts-paired-local.v1','complete':False,'passed':False,'orders':[['named','types'],['types','named'],['named','types']],'inputs':{str(p.relative_to(root)):identity(p) for p in files},'reports':[],'started_at':datetime.now(timezone.utc).isoformat()}
def save(): (result/'orchestration.json').write_text(json.dumps(report,sort_keys=True,indent=2)+'\n')
save()
try:
 for pair,order in enumerate(report['orders'],1):
  for condition in order:
   out=result/f'pair-{pair}-{condition}'
   argv=[sys.executable,str(root/'scripts/measure-incremental.py'),'--out',str(out),'--repetitions','5','--warmups','2','--timeout','60','--expect-arch','aarch64','--environment-note','Apple M4 macOS ARM64; same checkout, compiler, cwd and environment; only call-type-contracts differs; AB BA AB; full parsing and current reference reconstruction; native acceptance outside timing; warm caches/background load uncontrolled; no competing agent tests/builds']
   if condition=='types': argv.append('--call-type-contracts')
   row={'pair':pair,'condition':condition,'argv':argv,'returncode':None};report['reports'].append(row);save()
   with (result/(out.name+'.log')).open('wb') as log:
    row['returncode']=subprocess.run(argv,cwd=root,env={**os.environ,'LC_ALL':'C','PYTHONHASHSEED':'0','PYTHONDONTWRITEBYTECODE':'1'},stdout=log,stderr=subprocess.STDOUT).returncode
   save();assert row['returncode']==0,row
   d=json.loads((out/'report.json').read_text());assert d['complete'] and d['passed'] and len(d['samples'])==336 and all(s['verified'] for s in d['samples'])
   row['report_sha256']=identity(out/'report.json');save();print(out.name,'accepted',flush=True)
 for pair in range(1,4):
  a=json.loads((result/f'pair-{pair}-named/report.json').read_text());b=json.loads((result/f'pair-{pair}-types/report.json').read_text())
  for key in ('compiler_hash','inputs','python_executable','c_executable','c_version','c_target','c_flags','effective_environment_hash','working_directory_hash','garbage_collector','in_process_environment'):
   assert a[key]==b[key],key
  for aw,bw in zip(a['workloads'],b['workloads']):
   assert aw['id']==bw['id'] and aw['criteria']==bw['criteria']
   for ar,br in zip(aw['revisions'],bw['revisions']):
    for key in ('id','source','diagnostic'):assert ar.get(key)==br.get(key),key
    if ar['native_acceptance']:
     for key in ('generated_c','oracle'): assert ar['native_acceptance'][key]==br['native_acceptance'][key],key
  for ar,br in zip(a['samples'],b['samples']):
   for key in ('phase','repetition','workload','revision','mode','verified'):assert ar[key]==br[key],key
 for path in files:assert identity(path)==report['inputs'][str(path.relative_to(root))]
 report.update(complete=True,passed=True)
finally:
 report['finished_at']=datetime.now(timezone.utc).isoformat();save()

