#include <stdint.h>
struct tv_s_P { int32_t tv_m_x; };
extern int32_t tv_f_read(const struct tv_s_P *);
extern int32_t tv_f_bump(struct tv_s_P *);
extern int32_t tv_f_main(void);
int main(void) {
{ struct tv_s_P p = {-1000}; if (tv_f_read(&p) != -1000 || p.tv_m_x != -1000) return 1; if (tv_f_bump(&p) != -999 || p.tv_m_x != -999) return 1; }
{ struct tv_s_P p = {0}; if (tv_f_read(&p) != 0 || p.tv_m_x != 0) return 1; if (tv_f_bump(&p) != 1 || p.tv_m_x != 1) return 1; }
{ struct tv_s_P p = {1000000}; if (tv_f_read(&p) != 1000000 || p.tv_m_x != 1000000) return 1; if (tv_f_bump(&p) != 1000001 || p.tv_m_x != 1000001) return 1; }
return tv_f_main() == 0 ? 0 : 1;
}

